class Solution:
    def treeToDoublyList(self, root):
        if not root:
            return None
        self.first = None
        self.last = None
        def inorder(node):
            if not node:
                return
            inorder(node.left)
            if self.last:
                self.last.right = node
                node.left = self.last
            else:
                self.first = node
            self.last = node
            inorder(node.right)
        inorder(root)
        self.first.left = self.last
        self.last.right = self.first
        return self.first

